import { generateStageReportContent } from "../../watch/index.js";
import { redactSecretsText } from "../../../shared/redactSecrets.js";
import { recordReliabilitySample } from "../../watch/reliabilityShared.js";
import { stageWantsReport } from "../../promptCuration.js";
import { stageElapsedSeconds } from "../stagePolicy.js";
import { resolveStagesForTask } from "../stageResolution.js";
import { normalizeStageType } from "../../projectStore.js";
import { routeStageError } from "./routeStageError.js";
import { parkTaskForSurvey } from "./parkTaskForSurvey.js";

/***
 * MARK: applyRunnerReport
 * @description Engine-owned finish for a Runner-reported stage (remote
 *   dispatch integration, ADR 0009 step 6). The Runner owns git
 *   (clone/worktree/commit/push — transport row 1/2, D2: the backend never
 *   touches remotes for Runner work); the backend owns everything else,
 *   composing the SAME standalone transitions as the embedded path:
 *   formal report save (opt-in stages), reliability sample, question-me
 *   survey park (shared with executeStage — a remote run can never skip
 *   the human survey), failure routing via routeStageError, and
 *   advanceStage plus the scheduler follow-on kick. Call only after the
 *   lease fence accepted the execution (complete-execution does that).
 * @example await applyRunnerReport({ store, projectStore, projectId: 'p', taskId: 't', outcome: { status: 'passed', output: '...' } }) => { advanced: true, ... }
 * @param {Object} args - Context.
 * @param {Object} args.store - Task store.
 * @param {Object} args.projectStore - Project store.
 * @param {string} args.projectId - Project id.
 * @param {string} args.taskId - Task id.
 * @param {Object} args.outcome - Runner outcome.
 * @param {string} args.outcome.status - `passed` or `failed`.
 * @param {string} [args.outcome.output] - Final assistant text.
 * @param {string} [args.outcome.summary] - Run summary.
 * @param {Array} [args.outcome.modifiedFiles] - Modified files.
 * @param {string} [args.outcome.harnessId] - Harness that ran.
 * @param {string} [args.outcome.failureKind] - Failure taxonomy kind.
 * @param {string} [args.outcome.failureReason] - Failure message.
 * @param {string} [args.outcome.duration] - Run duration seconds.
 * @param {string} [args.outcome.runnerId] - Reporting Runner.
 * @returns {Promise<Object>} `{ advanced, status, ... }`.
 ***/
export async function applyRunnerReport({
	store,
	projectStore,
	projectId,
	taskId,
	outcome,
}) {
	const task = store.getTask(projectId, taskId);
	if (!task) {
		const err = new Error(`Task ${taskId} not found`);
		err.statusCode = 404;
		err.code = "TASK_NOT_FOUND";
		throw err;
	}
	const project = projectStore?.getProject?.(projectId);
	// The runner's completion payload (final assistant text, summaries) is
	// committed to the repository via stage reports and task markdown — the
	// same guarantee as the live log path: redact before persistence.
	// Structured log entries ingested live are already redacted at creation.
	const redactedOutput = redactSecretsText(outcome.output || "");
	const redactedSummary = redactSecretsText(outcome.summary || "");
	const stages = resolveStagesForTask(project, task);
	const stage =
		stages.find(
			(s) =>
				String(s.id) === String(task.currentStageId) ||
				(s.name &&
					String(s.name).toLowerCase() ===
						String(task.currentStageId).toLowerCase()),
		) ||
		stages[0] || { id: "stage", name: "Stage", type: "agent" };
	const stageType = normalizeStageType(stage.type);
	const bridge = store.eventBridge;
	const cwd = project?.cwd;
	const via = outcome.runnerId ? `via Runner ${outcome.runnerId}` : "via Runner";
	const duration = outcome.duration || "0.0";

	if (outcome.status === "failed") {
		const err = new Error(outcome.failureReason || "Stage failed on the Runner");
		// The runner's completion payload carries the tail of the run output
		// (runner/daemon.js caps it). Keep it on the error so the failure
		// report renders the actual failing output instead of only the
		// reason — thin "exit code 1" reports hid every branch result
		// (task b5716327). handleStageFailure already renders error.stdout
		// into the report, lastError, and timeline excerpt.
		if (redactedOutput) err.stdout = redactedOutput;
		return routeStageError(
			store,
			projectId,
			taskId,
			stage,
			err,
			{
				stages,
				bridge,
				projectCwd: cwd,
				runOutcome: {
					harnessId: outcome.harnessId,
					failureKind: outcome.failureKind,
				},
				classifyAs: {
					failureKind: outcome.failureKind,
					failureReason: outcome.failureReason,
				},
			},
		);
	}

	const at = Date.now();
	recordReliabilitySample(store, projectId, taskId, {
		harnessId: outcome.harnessId || "unknown",
		failureKind: "none",
		at,
		atRaw: new Date(at).toISOString(),
		stageId: stage.id,
	});
	bridge?.emitSystemLog?.(
		projectId,
		`[SYSTEM] Stage '${stage.name || stage.id}' completed in ${duration}s (${via})`,
		{ taskId, stageId: stage.id, duration },
	);

	if (stageWantsReport(stage)) {
		const reportContent = generateStageReportContent({
			task,
			stage,
			output: redactedOutput,
			summary: redactedSummary,
			modifiedFiles: outcome.modifiedFiles || [],
			status: "PASSED",
			duration,
		});
		store.saveStageReport(projectId, taskId, {
			stageName: stage.name || stage.id,
			stageId: stage.id,
			duration: stageElapsedSeconds(task),
			status: "PASSED",
			content: reportContent,
			projectCwd: cwd,
			harnessId: outcome.harnessId,
			failureKind: outcome.failureKind || "none",
		});
	}

	task.history.push({
		timestamp: new Date().toISOString(),
		action: `Agent stage completed: ${stage.name || stage.id} (${via})`,
	});
	store._saveTaskMarkdown(cwd, task);

	const surveyPark = parkTaskForSurvey({
		store,
		projectId,
		taskId,
		task,
		stage,
		projectObj: project,
		cwd,
		bridge,
		stageType,
		finalOutput: redactedOutput,
		streamedOutput: redactedOutput,
		summary: redactedSummary,
		modifiedFiles: outcome.modifiedFiles || [],
		duration,
		via,
	});
	if (surveyPark.parked) return { advanced: false, ...surveyPark.response };

	task.surveyPending = false;
	task.infraRetryCount = 0;
	store.advanceStage(projectId, taskId, stages, bridge, cwd);

	store.lastCompletedTask = { projectId, taskId, timestamp: Date.now() };
	if (store.schedulerRunning) {
		setTimeout(() => {
			store.scheduleTick().catch(() => {});
		}, 50);
	}

	return {
		advanced: true,
		task,
		stageType,
		status: "passed",
		output: redactedOutput,
		summary: redactedSummary,
		modifiedFiles: outcome.modifiedFiles || [],
		model: stage.model || null,
		duration,
	};
}

/**
 * MARK: redactSecrets
 * @description Single content-redaction choke point for every log surface
 *   (embedded agent stream, runner ingest, committed task markdown, live
 *   socket payloads, report output tails). The only secret knowledge the
 *   engine previously had was the child-env name pattern
 *   (`SECRET_NAME_PATTERN` in `api/agent/harnesses/shared/harnessScaffold.js`,
 *   which drops secret-shaped env vars before spawning); anything a model,
 *   tool, or vendor echoed back into log TEXT was stored verbatim. This
 *   module redacts secret and PII shapes inside already-rendered text, so
 *   producers keep their grammar and clean inputs pass through byte-identical.
 *
 *   Pure module: zero dependencies, no harness imports — safe to import from
 *   the runner bundle, the log processor, and the UI.
 */

/***
 * MARK: REDACTED
 * @description Replacement markers. Each category keeps its own marker so a
 *   redacted log still tells the reader WHAT kind of value was hidden (a
 *   token vs an email vs a home directory) without revealing any of it.
 * @example REDACTED.TOKEN => '[REDACTED]'
 ***/
export const REDACTED = Object.freeze({
	SECRET: "[REDACTED]",
	TOKEN: "[REDACTED]",
	EMAIL: "[REDACTED EMAIL]",
	PHONE: "[REDACTED PHONE]",
	CARD: "[REDACTED CARD]",
	PATH: "[REDACTED]",
	KEY: "[REDACTED PRIVATE KEY]",
});

/***
 * MARK: redactSecretsText
 * @description Redacts secret and PII shapes inside one text value.
 *   Non-strings return "" (mirrors `stripAnsiText`); clean text returns
 *   unchanged (same reference semantics as String.replace with no match —
 *   callers can rely on byte-identical output for secret-free inputs).
 * @example redactSecretsText('hi') => 'hi'
 * @example redactSecretsText('Bearer abcdefgh1234') => 'Bearer [REDACTED]'
 * @param {string} text - Rendered log text that may carry secrets.
 * @returns {string} The text with secret/PII shapes replaced.
 ***/
export const redactSecretsText = (text) => {
	if (typeof text !== "string" || !text) return "";
	let out = text;
	// Private key blocks first: they span lines and contain base64 that
	// later patterns would only partially redact.
	out = out.replace(
		/-----BEGIN [A-Z0-9 ]*PRIVATE KEY-----[\s\S]*?-----END [A-Z0-9 ]*PRIVATE KEY-----/g,
		REDACTED.KEY,
	);
	// Bearer / Basic authorization headers.
	out = out.replace(/(bearer\s+)[A-Za-z0-9._~+/=-]{8,}/gi, `$1${REDACTED.SECRET}`);
	out = out.replace(/(basic\s+)[A-Za-z0-9._~+/=]{8,}/gi, `$1${REDACTED.SECRET}`);
	// Vendor token shapes.
	out = out.replace(/sk-(?:live|test|proj)-[A-Za-z0-9]{8,}/g, "sk-[REDACTED]");
	out = out.replace(/xox[baprs]-[A-Za-z0-9-]{8,}/g, "xox-[REDACTED]");
	out = out.replace(/\bgh[pousr]_[A-Za-z0-9]{8,}/g, "gh_[REDACTED]");
	out = out.replace(/AIza[0-9A-Za-z_-]{35}/g, "AIza[REDACTED]");
	out = out.replace(/AKIA[0-9A-Z]{16}/g, "AKIA[REDACTED]");
	// Connection strings and embedded-credential URLs: keep the scheme so
	// the reader still knows the backend kind, drop everything secret.
	out = out.replace(
		/(postgres(?:ql)?|mysql|mongodb(?:\+srv)?|redis(?:s)?|amqp(?:s)?):\/\/[^\s"'`]+/gi,
		`$1://${REDACTED.SECRET}`,
	);
	out = out.replace(/(\w+:\/\/[^/\s:]+:)[^@\s/]+@/g, `$1${REDACTED.SECRET}@`);
	// AWS-style secret access keys inside JSON credential blobs.
	out = out.replace(
		/("(?:aws_secret|secret_access_key|session_token)"\s*:\s*")[^"]*(")/gi,
		`$1${REDACTED.SECRET}$2`,
	);
	// Labeled key/value pairs: api_key=..., "password": "...", CLIENT_SECRET: ...
	// The key list mirrors SECRET_NAME_PATTERN plus wire formats (apiKey,
	// client_secret, authToken). A real `:`/`=` separator is required — bare
	// prose ("secret reasoning step one") must never redact — and the value
	// needs at least 6 chars so short words after a colon survive.
	out = out.replace(
		/\b(api[_-]?key|auth[_-]?token|client[_-]?secret|credential(?:s)?|passwd|password|pwd|secret|token)\b(\s*["']?\s*[:=][=>]?\s*["']?)([A-Za-z0-9._~+/=:@-]{6,})/gi,
		`$1$2${REDACTED.SECRET}`,
	);
	// ENV-style assignments with secret-shaped names: FOOBAR_API_KEY="...".
	out = out.replace(
		/\b([A-Z][A-Z0-9_]*(?:SECRET|TOKEN|PASSWORD|PASSWD|PWD|CREDENTIAL|API[_-]?KEY|PRIVATE[_-]?KEY)[A-Z0-9_]*)\s*=\s*("[^"]*"|'[^']*'|[^\s,;}\]]+)/g,
		`$1=${REDACTED.SECRET}`,
	);
	// PII: emails, home directories (never /tmp or repo-relative paths),
	// phone shapes, and spaced/dashed 16-digit card runs.
	out = out.replace(
		/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g,
		REDACTED.EMAIL,
	);
	out = out.replace(/\/(home|Users)\/[^\s/"'`:\n]+/g, `/$1/${REDACTED.PATH}`);
	out = out.replace(
		/\b(?:\+?1[-.\s]?)?\(?\d{3}\)?[-.\s]\d{3}[-.\s]\d{4}\b/g,
		REDACTED.PHONE,
	);
	out = out.replace(/\b\d{4}[- ]\d{4}[- ]\d{4}[- ]\d{4}\b/g, REDACTED.CARD);
	return out;
};

/***
 * MARK: SECRET_KEY_PATTERN
 * @description Secret-shaped object key names (mirrors `SECRET_NAME_PATTERN`
 *   in `api/agent/harnesses/shared/harnessScaffold.js`, extended to wire
 *   spellings like `apiKey`/`client_secret`). A string value under one of
 *   these keys is a secret by position even when the value itself carries no
 *   recognizable shape — the same rule the child-env seam already enforces.
 * @example SECRET_KEY_PATTERN.test("apiKey") => true
 * @example SECRET_KEY_PATTERN.test("model") => false
 ***/
export const SECRET_KEY_PATTERN =
	/secret|token|password|passwd|pwd|credential|api[_-]?key|private[_-]?key|access[_-]?key|client[_-]?secret|auth/i;

/***
 * MARK: redactDeepStrings
 * @description Deep-clones a JSON-ish value while redacting every string it
 *   contains. Used for structured payloads (tool args/results, permission
 *   targets, raw evidence) where a secret may sit in a nested field, not in
 *   rendered text. A string under a secret-shaped key (`SECRET_KEY_PATTERN`)
 *   is redacted by position even when the value looks innocent; numbers,
 *   booleans, null, and undefined pass through untouched (so usage token
 *   counts survive); circular values degrade to "[Unserializable]" instead of
 *   throwing.
 * @example redactDeepStrings({ a: 'Bearer abcdefgh1234' }) => { a: 'Bearer [REDACTED]' }
 * @param {*} value - Any JSON-ish value.
 * @returns {*} A redacted deep clone.
 ***/
export const redactDeepStrings = (value) => {
	// Ancestor set only: a reference shared between siblings is cloned twice,
	// while a true cycle (an object reachable from itself) degrades safely.
	const ancestors = new Set();
	const walk = (node) => {
		if (typeof node === "string") return redactSecretsText(node);
		if (!node || typeof node !== "object") return node;
		if (ancestors.has(node)) return "[Unserializable]";
		ancestors.add(node);
		try {
			if (Array.isArray(node)) return node.map(walk);
			const out = {};
			for (const key of Object.keys(node)) {
				// eslint-disable-next-line security/detect-object-injection -- key comes from Object.keys of the walked object
				const child = node[key];
				if (typeof child === "string" && SECRET_KEY_PATTERN.test(key)) {
					// eslint-disable-next-line security/detect-object-injection -- key comes from Object.keys of the walked object
					out[key] = REDACTED.SECRET;
				} else {
					// eslint-disable-next-line security/detect-object-injection -- key comes from Object.keys of the walked object
					out[key] = walk(child);
				}
			}
			return out;
		} finally {
			ancestors.delete(node);
		}
	};
	return walk(value);
};

