function ensureCompileCache() {
	if (!process.env.NODE_COMPILE_CACHE) {
		process.env.NODE_COMPILE_CACHE = path.join(os.tmpdir(), "kainbain-compile-cache");
	}
	fs.mkdirSync(process.env.NODE_COMPILE_CACHE, { recursive: true });
}

