		git(repoDir, ["add", "."]);
		git(repoDir, ["commit", "-m", "feat(session): first draft"]);
		fs.appendFileSync(path.join(repoDir, "src/session.js"), "const extra = 4;\n");
		git(repoDir, ["add", "."]);
		git(repoDir, ["commit", "-m", "feat(session): add extra"]);
