					).json();
					return `${t.status} :: ${(t.failureReason || "").slice(0, 300)}`;
				},
				{ timeout: 30000 },
			)
			.toMatch(/^completed ::/);
		const merged = git(repoDir, ["show", "main:src/session.js"]);
		expect(merged).toContain("if (b == null) return 0;");
	});

